By \cite[\S VII.8, principal theorem, pp.~598--599;
\S VIII.1, Theorem~1 and its corollary, p.~600]{Douady1974},
there is a minimal versal analytic germ with tangent space $H^1(T_X)$.

\begin{remark}[A punctured isomorphism with an essential singularity]
\hypertarget{tag-PT03}{}\label{I:essential-punctured-isomorphism}
\StatementRecord{I:essential-punctured-isomorphism}{proved}{PT03}{}
The automorphism
\[
 (s,[z_0:z_1])\longmapsto(s,[e^{1/s}z_0:z_1])
\]
of $\Delta^*\times\mathbb P^1$ has no meromorphic extension across zero, although the two product families extend properly over the disc. Its restriction to the constant section $[1:1]$ is $[e^{1/s}:1]$, which has an essential singularity. The proper graph of a meromorphic extension, pulled back to this section and normalized in its dominating component, would give a holomorphic extension from the disc, a contradiction.
\end{remark}

\begin{remark}[The distinguished orbit on an ordinary torus]
\hypertarget{tag-PT04}{}\label{I:noncompactifiable-distinguished-orbit}
\StatementRecord{I:noncompactifiable-distinguished-orbit}{proved}{PT04}{}
The distinguished nonconstant orbit map $\mathbb C^*\to T^2$ on an ordinary torus has no meromorphic extension to $\mathbb P^1$. A meromorphic map from a smooth curve to a compact complex manifold extends holomorphically at its isolated indeterminacies, by normalization of its proper graph. A holomorphic map $\mathbb P^1\to T^2$ lifts to $\mathbb C^2$ and is constant. This contradicts the nonconstant orbit map.
\end{remark}

\begin{remark}[Vertical divisors and component adjunction]
\hypertarget{tag-PT05}{}\label{I:vertical-divisor-adjunction}
\StatementRecord{I:vertical-divisor-adjunction}{proved}{PT05}{}
For a proper semistable surface family with smooth total space and reduced simple normal-crossing central divisor $\sum_i V_i$, let a nonzero meromorphic relative two-form have vertical divisor $\sum_i a_iV_i$. Put $C_{ij}=V_i\cap V_j$ and $C_i=\sum_{j\ne i}C_{ij}$. Then
\[
 K_{V_i}+C_i\sim\sum_{j\ne i}(a_j-a_i)C_{ij}.\tag{B.4.28.11}
\]
Indeed, adjunction gives $K_{V_i}=(K_{\mathcal X/\Delta}+V_i)|_{V_i}$, while the principal total fibre gives $\mathcal O_{\mathcal X}(V_i)|_{V_i}\sim-C_i$. Restricting the divisor of the form yields the displayed equality.
\end{remark}

\begin{definition}[Cohomological conventions]
\hypertarget{tag-PI13}{}\label{I:def:hodge-conventions}
For the standard marked threefold, put $h=h^{1,2}(X)$.
Proposition~\ref{inv:A3.1} gives $h=1$. We write the dimensions
below as functions of $h$ in the common Hodge pattern
\begin{equation}\hypertarget{tag-01TF}{}\label{inv:eq:C-hodge-input}
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&0&1\\
2&0&h&h+1&1\\
1&1&h+1&h&0\\
0&1&0&0&0.
\end{array}
\end{equation}
The numerical tables of this family are obtained by the evaluation
map $\mathbb Z[h]\to\mathbb Z$, $h\mapsto1$.
We use $d=\partial+\bar\partial$ on complex-valued smooth forms
and the complex orientation for integration.
\end{definition}

\begin{proposition}[Bott--Chern and Aeppli tables as functions of $h$]\hypertarget{tag-01SC}{}\label{inv:C2.1}\label{wb:thm:exact-bott-chern-aeppli}
\StatementRecord{inv:C2.1}{proved}{01SC}{\SeriesRef{inv:A3.1}, \SeriesRef{inv:C1.1}, \SeriesRef{inv:eq:C-arrows}; \citet[Theorem 3]{Stelzig2021}; \citet[Proposition 6(1)]{Stelzig2021}}

The complete dimension tables are
\begin{equation}\hypertarget{tag-01T6}{}\label{inv:eq:C-BC-A}
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&1&1\\
2&0&h&2h&1\\
1&0&2&h&0\\
0&1&0&0&0
\end{array}_{BC}
\qquad
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&0&1\\
2&0&h&2&0\\
1&1&2h&h&0\\
0&1&1&0&0.
\end{array}_{A}
\end{equation}
At the value $h=1$ of Proposition~\ref{inv:A3.1},  The totals are
$(1,0,2,2,2,2,1)$ and $(1,2,2,2,2,0,1)$, respectively.
\end{proposition}


\begin{proof}
\begin{enumerate}[label=\arabic*.,leftmargin=*]
\item Apply \cite[Theorem~3, p.~7; Proposition~6, p.~16;
Lemma~8, p.~17]{Stelzig2021} to the bounded-bidegree complex of
smooth forms. The theorem permits arbitrary cardinal dimensions.
Its odd zigzags contribute to total cohomology; the sphere Betti
groups and the single extreme bidegrees therefore leave only dots
at $(0,0)$ and $(3,3)$. By \cref{inv:C1.1} and conjugation,
both spectral sequences have no differential after $d_1$, so every
remaining zigzag is an arrow. The horizontal arrows are exactly
\begin{equation}\hypertarget{tag-01TA}{}\label{inv:eq:C-arrows}
\begin{array}{c|c|r}
\text{source}&\text{target}&\text{multiplicity}\\\hline
(0,1)&(1,1)&1\\
(1,1)&(2,1)&h\\
(1,2)&(2,2)&h\\
(2,2)&(3,2)&1.
\end{array}
\end{equation}
The vertical arrows are their reflections in $p=q$.

\item Under the cited decomposition, an arrow contributes its target
to Bott--Chern cohomology and its source to Aeppli cohomology;
a dot contributes to both and a square to neither. The induced
isomorphisms in Lemma~8 respect the two definitions in the statement.
Counting the displayed arrows and their reflections gives every
entry of \eqref{inv:eq:C-BC-A}. Kernels, images and these quotients
commute with direct sums, including the possible infinite sum of
squares.

\item The program
\path{code/current_audits/audit_paper_i/code/main_D_double_complex.py}
uses rational Gaussian elimination with Python fractions to compute
both cohomologies directly from their kernels and images. For each
$h=0,\ldots,5$, it includes an anticommuting acyclic square,
computes the induced $d_1$ on column cohomology and the total
cohomology, and compares with a separate corner count. All
54 checks pass; its matrices and tables are saved in
\path{main_D_double_complex.output.json}. These finite calculations
corroborate the universal decomposition argument above.
\end{enumerate}
\end{proof}

