\begin{definition}[Higher multiplicities and source coordinates]
\hypertarget{tag-IP10}{}\label{I:def:higher-multiplicity-coordinates}
\StatementRecord{I:def:higher-multiplicity-coordinates}{proved}{IP10}{}
Put $m=3k$, $n=4l$ with $\gcd(m,n)=1$.
Viaclovsky's indices $(0,1)$ correspond to the finite indices $(1,2)$
of \cref{def:common-conventions}. Lattice coordinates are integral
homology coordinates, and matrices act on columns.
\end{definition}

\begin{definition}[Cohomological conventions]
\hypertarget{tag-PI13}{}\label{I:def:hodge-conventions}
\StatementRecord{I:def:hodge-conventions}{proved}{PI13}{}
For the standard marked threefold, put $h=h^{1,2}(X)$.
Proposition~\ref{inv:A3.1} gives $h=1$. We write the dimensions
below as functions of $h$ in the common Hodge pattern
\begin{equation}\hypertarget{tag-01TF}{}\label{inv:eq:C-hodge-input}
\begin{array}{c|rrrr}
q\backslash p&0&1&2&3\\\hline
3&0&0&0&1\\
2&0&h&h+1&1\\
1&1&h+1&h&0\\
0&1&0&0&0.
\end{array}
\end{equation}
The numerical tables of this family are obtained by the evaluation
map $\mathbb Z[h]\to\mathbb Z$, $h\mapsto1$.
We use $d=\partial+\bar\partial$ on complex-valued smooth forms
and the complex orientation for integration.

\begin{definition}[The current convention]
\hypertarget{tag-IA07}{}\label{I:current-convention}
\StatementRecord{I:current-convention}{proved}{IA07}{}

We take $dd^c=(i/\pi)\partial\bar\partial$, so that
$dd^c\log|w|=\delta_0$. For a local complex coordinate $w$,
$dA_w=(i/2)dw\wedge d\bar w$.

