\begin{theorem}[Classification of the standard family]\hypertarget{tag-01Q6}{}\label{fam:src:A.5.1}\label{fam:st:A.5.1}\label{wb:pshift:thm:classification}\hypertarget{tag-000C}{}\label{app:rederive:fam-src-A.5.1}
